// solidity-coverage config. skipFiles are relative to contracts/.
//
// contracts/test and contracts/mocks are test doubles. The verifiers are
// generated by snarkJS and rewritten by setup:zk; instrumenting them only
// adds noise. Run `npx hardhat clean` after changing this list.
//
// Do NOT run a plain `hardhat test` or `hardhat compile` in this tree while a
// coverage run is in flight: the plugin compiles instrumented bytecode into
// artifacts/ and a plain compile silently overwrites it, so every suite that
// deploys afterwards records zero coverage while still passing.
module.exports = {
  skipFiles: ["test", "mocks", "privacy/verifiers"],
};
